:2px solid #555;border-radius:4px;display:flex;align-items:center;justify-content:center;text-align:center;padding:4px;font-size:11px;font-weight:700;cursor:move;user-select:none;touch-action:none}.item.selected{outline:3px solid var(--accent);outline-offset:2px;z-index:9999!important}.item .resize{display:none;position:absolute;right:-6px;bottom:-6px;width:14px;height:14px;border:2px solid #fff;border-radius:3px;background:var(--accent);cursor:nwse-resize}.item.selected .resize{display:block}.item .dim{position:absolute;bottom:-18px;left:50%;transform:translateX(-50%);font-size:9px;white-space:nowrap;background:#fff;padding:1px 4px;border-radius:3px;color:#555}.table{background:#b98959;border-color:#735135}.chair{background:#6d4d34;color:#fff;border-radius:50%}.bar{background:#493526;color:#fff}.cold{background:#dff1f7;border-color:#5b9cad}.hot{background:#f6dfd4;border-color:#b66d4d}.steel{background:#e4e7eb;border-color:#7b838d}.storage{background:#eee8d9;border-color:#9b8d68}.gelato{background:#fff1b8;border-color:#ae8400}.host{background:#e6ddd0;border-color:#97765b}.zone{background:rgba(37,99,235,.05);border:2px dashed #6b8be0}.aisle{background:rgba(255,184,0,.07);border:2px dashed #c69300}.wall{background:#111;border-color:#111}.door{background:#fff;border:2px dashed #555}.field{margin-bottom:9px}.field label{display:block;font-size:11px;color:#666;margin-bottom:4px}.field input,.field select{width:100%;padding:7px;border:1px solid var(--line);border-radius:7px}.two{display:grid;grid-template-columns:1fr 1fr;gap:7px}.three{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:7px}.card{border:1px solid var(--line);border-radius:9px;padding:9px;background:#fafbfc}.card .v{font-size:20px;font-weight:850}.card .k{font-size:9px;color:#737a84;text-transform:uppercase}.card.wide{grid-column:1/-1}.note{font-size:11px;color:#727983;line-height:1.45}.warn{padding:8px;border:1px solid #efcf79;background:#fff9e8;bor