<script>
(()=>{'use strict';const CAN_EDIT=<?= $canEdit ? 'true':'false' ?>,CSRF=<?= json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?>,$=id=>document.getElementById(id),stage=$('stage'),holder=$('holder');let selected=null,dragType='',z=50,zoom=1,planW=50,planH=34,scale=24,activeId='';
const defs={table:['4-TOP','table',48,36,4,'dining'],chair:['','chair',20,20,1,'dining'],bar:['BAR','bar',180,120,20,'bar'],host:['HOST','host',36,24,0,'none'],gelato:['GELATO','gelato',72,36,0,'none'],zone:['ZONE','zone',120,96,0,'none'],'pizza-oven':['PIZZA OVEN','hot',60,48,0,'none'],'dough-mixer':['DOUGH MIXER','steel',30,36,0,'none'],'prep-table':['REFRIGERATED PREP','cold',72,34,0,'none'],pizza:['PIZZA STATION','hot',108,34,0,'none'],salad:['SALAD STATION','cold',72,34,0,'none'],server:['SERVER STATION','steel',72,24,0,'none'],walkin:['WALK-IN COOLER','cold',120,96,0,'none'],keg:['KEG STORAGE','cold',72,30,0,'none'],wine:['WINE STORAGE','storage',36,24,0,'none'],shelving:['SHELVING','storage',48,18,0,'none'],sink3:['3-COMP SINK','steel',84,30,0,'none'],handsink:['HAND SINK','steel',18,18,0,'none'],dish:['DISH MACHINE','steel',30,30,0,'none'],'batch-freezer':['BATCH FREEZER','cold',24,30,0,'none'],'blast-freezer':['BLAST FREEZER','cold',30,32,0,'none'],wall:['','wall',120,6,0,'none'],door:['DOOR','door',36,6,0,'none'],aisle:['AISLE','aisle',48,120,0,'none']};
const px=inches=>inches/12*scale,inch=p=>p/scale*12,fmt=i=>{i=Math.max(0,Math.round(i));return `${Math.floor(i/12)}' ${i%12}\"`},snap=p=>Math.round(p/(scale/2))*(scale/2),money=n=>'$'+Math.round(n).toLocaleString(),status=t=>{const e=$('status');e.textContent=t;clearTimeout(e._t);e._t=setTimeout(()=>e.textContent='Ready',1800)};
function canvas(){const w=planW*scale,h=planH*scale;stage.style.width=w+'px';stage.style.height=h+'px';stage.style.transform=`scale(${zoom})`;holder.style.width=w*zoom+'px';holder.style.height=h*zoom+'px';document.documentElement.style.setProperty('--grid',scale/2+'px');$('sqft').value=(planW*planH).toLocaleString()+' sq ft'}
function badge(el){el.querySelector('.dim').textContent=`${fmt(inch(parseFloat(el.style.width)))} × ${fmt(inch(parseFloat(el.style.height)))}`}
function create(type,x=48,y=48,o={}){const d=defs[type]||defs.zone,el=document.createElement('div');el.className='item '+d[1];el.dataset.type=type;el.dataset.seats=o.seats??d[4];el.dataset.zone=o.zone??d[5];el.dataset.rot=o.rot??0;el.style.left=(o.x??snap(x))+'px';el.style.top=(o.y??snap(y))+'px';el.style.width=(o.w??px(d[2]))+'px';el.style.height=(o.h??px(d[3]))+'px';el.style.zIndex=o.z??++z;el.style.transform=`rotate(${el.dataset.rot}deg)`;el.innerHTML=`<span class="label"></span><span class="dim"></span><span class="resize"></span>`;el.querySelector('.label').textContent=o.label??d[0];stage.appendChild(el);bind(el);badge(el);return el}
function bind(el){el.addEventListener('pointerdown',e=>{if(!CAN_EDIT||e.button!==0||e.target.classList.contains('resize'))return;select(el);const sx=e.clientX,sy=e.clientY,sl=parseFloat(el.style.left),st=parseFloat(el.style.top);el.setPointerCapture(e.pointerId);const mv=v=>{el.style.left=Math.max(0,snap(sl+(v.clientX-sx)/zoom))+'px';el.style.top=Math.max(0,snap(st+(v.clientY-sy)/zoom))+'px';recalc()};const up=v=>{el.releasePointerCapture(v.pointerId);el.removeEventListener('pointermove',mv);el.removeEventListener('pointerup',up)};el.addEventListener('pointermove',mv);el.addEventListener('pointerup',up)});const h=el.querySelector('.resize');h.addEventListener('pointerdown',e=>{if(!CAN_EDIT)return;e.stopPropagation();select(el);const sx=e.clientX,sy=e.clientY,sw=parseFloat(el.style.width),sh=parseFloat(el.style.height);h.setPointerCapture(e.pointerId);const mv=v=>{el.style.width=Math.max(scale/2,snap(sw+(v.clientX-sx)/zoom))+'px';el.style.height=Math.max(scale/2,snap(sh+(v.clientY-sy)/zoom))+'px';badge(el);props();recalc()};const up=v=>{h.releasePointerCapture(v.pointerId);h.removeEventListener('pointermove',mv);h.removeEventListener('pointerup',up)};h.addEventListener('pointermove',mv);h.addEventListener('pointerup',up)})}
function select(el){document.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));selected=el;if(el)el.classList.add('selected');$('props').style.display=el?'block':'none';$('none').style.display=el?'none':'block';props()}
function props(){if(!selected)return;const wi=inch(parseFloat(selected.style.width)),hi=inch(parseFloat(selected.style.height));$('pLabel').value=selected.querySelector('.label').textContent;$('pWft').value=Math.floor(wi/12);$('pWin').value=Math.round(wi%12);$('pHft').value=Math.floor(hi/12);$('pHin').value=Math.round(hi%12);$('pSeats').value=selected.dataset.seats||0;$('pZone').value=selected.dataset.zone||'none'}
function applyProps(){if(!CAN_EDIT||!selected)return;selected.querySelector('.label').textContent=$('pLabel').value;const wi=(+$('pWft').value||0)*12+(+$('pWin').value||0),hi=(+$('pHft').value||0)*12+(+$('pHin').value||0);selected.style.width=Math.max(scale/2,px(wi))+'px';selected.style.height=Math.max(scale/2,px(hi))+'px';selected.dataset.seats=+$('pSeats').value||0;selected.dataset.zone=$('pZone').value;badge(selected);recalc()}
['pLabel','pWft','pWin','pHft','pHin','pSeats','pZone'].forEach(id=>$(id).addEventListener('input',applyProps));
document.querySelectorAll('.pal').forEach(p=>{p.addEventListener('dragstart',e=>{if(!CAN_EDIT){e.preventDefault();return}dragType=p.dataset.type;e.dataTransfer.setData('text/plain',dragType)});p.addEventListener('click',()=>{if(!CAN_EDIT)return;select(create(p.dataset.type));recalc()})});stage.addEventListener('dragover',e=>{if(CAN_EDIT)e.preventDefault()});stage.addEventListener('drop',e=>{if(!CAN_EDIT)return;e.preventDefault();const r=stage.getBoundingClientRect(),type=e.dataTransfer.getData('text/plain')||dragType;select(create(type,(e.clientX-r.left)/zoom,(e.clientY-r.top)/zoom));recalc()});stage.addEventListener('pointerdown',e=>{if(e.target===stage)select(null)});
$('del').onclick=()=>{if(CAN_EDIT&&selected){selected.remove();select(null);recalc()}};$('dup').onclick=()=>{if(!CAN_EDIT||!selected)return;const d=ser(selected);d.x+=scale;d.y+=scale;select(create(d.type,d.x,d.y,d));recalc()};$('rot').onclick=()=>{if(CAN_EDIT&&selected){selected.dataset.rot=((+selected.dataset.rot||0)+90)%360;selected.style.transform=`rotate(${selected.dataset.rot}deg)`}};$('front').onclick=()=>{if(CAN_EDIT&&selected)selected.style.zIndex=++z};
function ser(el){return{type:el.dataset.type,label:el.querySelector('.label').textContent,x:parseFloat(el.style.left),y:parseFloat(el.style.top),w:parseFloat(el.style.width),h:parseFloat(el.style.height),rot:+el.dataset.rot||0,z:+el.style.zIndex||1,seats:+el.dataset.seats||0,zone:el.dataset.zone||'none'}}function revenue(){return{lOcc:+$('lOcc').value,lTurns:+$('lTurns').value,lCheck:+$('lCheck').value,dOcc:+$('dOcc').value,dTurns:+$('dTurns').value,dCheck:+$('dCheck').value,barPct:+$('barPct').value,gelPct:+$('gelPct').value,gelAvg:+$('gelAvg').value}}function data(){return{version:3,planWft:planW,planHft:planH,scale,revenue:revenue(),items:[...stage.querySelectorAll('.item')].map(ser)}}function load(d){stage.querySelectorAll('.item').forEach(x=>x.remove());select(null);planW=+d.planWft||50;planH=+d.planHft||34;scale=+d.scale||24;$('planW').value=planW;$('planH').value=planH;$('scale').value=scale;if(d.revenue)Object.entries(d.revenue).forEach(([k,v])=>{if($(k))$(k).value=v});canvas();(d.items||[]).forEach(i=>create(i.type,i.x,i.y,i));z=Math.max(50,...(d.items||[]).map(i=>i.z||1));recalc()}
function rect(el){return{x:parseFloat(el.style.left),y:parseFloat(el.style.top),w:parseFloat(el.style.width),h:parseFloat(el.style.height)}}function gap(a,b){const dx=Math.max(a.x-b.x-b.w,b.x-a.x-a.w,0),dy=Math.max(a.y-b.y-b.h,b.y-a.y-a.h,0);return Math.sqrt(dx*dx+dy*dy)}function recalc(){const items=[...stage.querySelectorAll('.item')];let ds=0,bs=0,ps=0;items.forEach(el=>{const n=+el.dataset.seats||0;if(el.dataset.zone==='dining')ds+=n;if(el.dataset.zone==='bar')bs+=n;if(el.dataset.zone==='patio')ps+=n});const total=ds+bs+ps;$('dining').textContent=ds;$('barSeats').textContent=bs;$('patio').textContent=ps;$('capacity').textContent=total;const tables=items.filter(e=>e.dataset.type==='table');let mg=Infinity;for(let i=0;i<tables.length;i++)for(let j=i+1;j<tables.length;j++)mg=Math.min(mg,gap(rect(tables[i]),rect(tables[j])));$('spacing').textContent=isFinite(mg)?fmt(inch(mg)):'—';const ais=items.filter(e=>e.dataset.type==='aisle');let ma=Infinity;ais.forEach(e=>ma=Math.min(ma,inch(parseFloat(e.style.width))));$('aisle').textContent=isFinite(ma)?fmt(ma):'—';const r=revenue(),lc=total*(r.lOcc/100)*r.lTurns,dc=total*(r.dOcc/100)*r.dTurns,base=lc*r.lCheck+dc*r.dCheck,br=base*(r.barPct/100),gr=(lc+dc)*(r.gelPct/100)*r.gelAvg;$('lCovers').textContent=Math.round(lc);$('dCovers').textContent=Math.round(dc);$('barRev').textContent=money(br);$('gelRev').textContent=money(gr);$('dailyRev').textContent=money(base+br+gr);const w=[];if(isFinite(mg)&&inch(mg)<36)w.push(`Some tables are closer than 3' edge-to-edge (${fmt(inch(mg))}).`);if(isFinite(ma)&&ma<36)w.push(`A marked aisle is under 3' (${fmt(ma)}).`);const c=$('checks');c.className=w.length?'warn':'ok';c.innerHTML=w.length?w.join('<br>'):'No measured spacing issues detected.';$('sqft').value=(planW*planH).toLocaleString()+' sq ft'}['lOcc','lTurns','lCheck','dOcc','dTurns','dCheck','barPct','gelPct','gelAvg'].forEach(id=>$(id).addEventListener('input',recalc));
async function api(method='GET',payload=null,q=''){const o={method,headers:{Accept:'application/json'}};if(payload){o.headers['Content-Type']='application/json';o.body=JSON.stringify(payload)}const r=await fetch('api/floor-plans.php'+q,o);let j={};try{j=await r.json()}catch(e){}if(!r.ok||!j.ok)throw new Error(j.message||`Request failed (${r.status})`);return j}async function list(auto=false){try{const j=await api(),s=$('savedPlans'),cur=activeId||s.value;s.innerHTML='<option value="">Unsaved layout</option>'+j.plans.map(p=>`<option value="${p.id}">${p.name} · v${p.version}</option>`).join('');if(cur&&j.plans.some(p=>p.id===cur))s.value=cur;else if(auto&&j.plans.length){s.value=j.plans[0].id;await loadServer(j.plans[0].id)}}catch(e){status(e.message)}}async function loadServer(id=$('savedPlans').value){if(!id)return;try{status('Loading…');const j=await api('GET',null,'?id='+encodeURIComponent(id));activeId=j.plan.id;$('planName').value=j.plan.name;load(j.plan.data);$('savedPlans').value=activeId;status(`Loaded v${j.plan.version}`)}catch(e){alert(e.message)}}async function save(){if(!CAN_EDIT)return;const name=$('planName').value.trim();if(!name)return alert('Enter a layout name.');try{status('Saving…');const j=await api('POST',{csrf_token:CSRF,action:'save',plan:{id:activeId||null,name,data:data()}});activeId=j.plan.id;await list(false);$('savedPlans').value=activeId;status(`Saved v${j.plan.version}`)}catch(e){alert(e.message);status('Save failed')}}async function archive(){if(!CAN_EDIT||!activeId)return;if(!confirm('Archive this saved layout?'))return;try{await api('POST',{csrf_token:CSRF,action:'archive',id:activeId});activeId='';await list(false);status('Archived')}catch(e){alert(e.message)}}
$('saveBtn').onclick=save;$('loadBtn').onclick=()=>loadServer();$('archiveBtn').onclick=archive;$('savedPlans').onchange=()=>{if($('savedPlans').value)loadServer($('savedPlans').value)};$('back').onclick=()=>location.href='index.php';$('newBtn').onclick=()=>{if(!CAN_EDIT)return;if(confirm('Start a new blank layout?')){stage.querySelectorAll('.item').forEach(x=>x.remove());activeId='';$('savedPlans').value='';$('planName').value='New Layout';recalc()}};$('zoom').oninput=()=>{zoom=+$('zoom').value/100;canvas()};$('applyScale').onclick=()=>{if(!CAN_EDIT)return;const old=scale;planW=Math.max(10,+$('planW').value||50);planH=Math.max(10,+$('planH').value||34);scale=Math.max(8,+$('scale').value||24);if(old!==scale){const r=scale/old;stage.querySelectorAll('.item').forEach(el=>{el.style.left=parseFloat(el.style.left)*r+'px';el.style.top=parseFloat(el.style.top)*r+'px';el.style.width=parseFloat(el.style.width)*r+'px';el.style.height=parseFloat(el.style.height)*r+'px';badge(el)})}canvas();recalc()};
function seed(){const add=(t,x,y,o={})=>create(t,x*scale,y*scale,{...o,x:x*scale,y:y*scale,w:o.wFt?o.wFt*scale:undefined,h:o.hFt?o.hFt*scale:undefined});add('zone',.5,3,{wFt:8,hFt:26,label:'COVERED PATIO'});add('walkin',12,.5,{wFt:7,hFt:6});add('pizza-oven',20.5,1);add('server',11.5,7,{wFt:4,hFt:8.5,label:'PREP / SERVER'});add('salad',17,8.8,{wFt:8,hFt:3});add('pizza',25.5,8.8,{wFt:10,hFt:3});add('bar',21,18,{wFt:15,hFt:11.5,seats:20,zone:'bar'});add('host',42.3,28.2);add('gelato',46,23.5,{wFt:3,hFt:9});add('aisle',38.3,17,{wFt:4,hFt:12,label:'MAIN AISLE'});[[9.5,8.5],[9.5,14],[9.5,19.5],[9.5,25],[9.5,29],[15.5,28.5]].forEach(([x,y])=>add('table',x,y,{seats:4,zone:'dining'}));[[2.1,5],[2.1,11.8],[2.1,18.8],[2.1,25.7]].forEach(([x,y])=>add('table',x,y,{seats:4,zone:'patio'}));recalc()}canvas();seed();list(true);
})();
</script>
</body></html>
